                '<input type="checkbox" data-t="' + b[0] + '"' + (tiposSel[b[0]] ? ' checked' : '') + ' style="margin:0;width:11px;height:11px;accent-color:#e8ac0a">' + b[1].replace('Todos os recursos', 'Todos') + '</label>';
