      if (!r || r.erro || !r.plano) { box.innerHTML = '<div style="color:#ff6b6b;font-size:11px">Erro ao simular: ' + gerHtml((r && r.erro) || 'desconhecido') + '</div>'; return; }
      var p = r.plano, td = 'padding:3px 4px;font-size:11px;';
